import{_ as e,o as t,c as r,a0 as o}from"./chunks/framework.DwEC4Wzn.js";const p=JSON.parse('{"title":"关于与致谢","description":"","frontmatter":{},"headers":[],"relativePath":"guide/about.md","filePath":"guide/about.md","lastUpdated":null}'),i={name:"guide/about.md"};function n(l,a,s,d,u,h){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="关于与致谢" tabindex="-1">关于与致谢 <a class="header-anchor" href="#关于与致谢" aria-label="Permalink to &quot;关于与致谢&quot;">​</a></h1><p>PowerKit 是一个 Windows 11 电源管理托盘工具，用 Rust 编写，界面基于 egui/eframe。</p><ul><li><strong>当前版本</strong>：0.2.0（设置页「关于」页签显示的就是运行中程序的版本号）</li><li><strong>版权</strong>：© 2026 PowerKit · 保留所有权利</li><li><strong>形态</strong>：单进程托盘程序，无 .NET、无 WebView、无 VC++ 运行时依赖</li><li><strong>权限</strong>：不需要管理员权限，配置与自启项都写在 HKCU</li></ul><h2 id="许可与分发" tabindex="-1">许可与分发 <a class="header-anchor" href="#许可与分发" aria-label="Permalink to &quot;许可与分发&quot;">​</a></h2><p>程序<strong>闭源发行</strong>，源码仓库不公开。本站只提供安装版与便携版的下载说明，见 <a href="/powerkit-web/guide/install">下载与安装</a>。</p><h2 id="第三方组件" tabindex="-1">第三方组件 <a class="header-anchor" href="#第三方组件" aria-label="Permalink to &quot;第三方组件&quot;">​</a></h2><p>充电阈值接口使用的 RPC 客户端桩来自 MIT 协议的开源项目 <a href="https://github.com/alandau/LenPwrCtl" target="_blank" rel="noreferrer">LenPwrCtl</a>（作者 Alan Lau），其文件头保留原始许可声明。 该桩由联想电源管理接口的 IDL 经 MIDL 生成，按 x64 / ARM64 各编一份。</p><h2 id="硬件接口说明" tabindex="-1">硬件接口说明 <a class="header-anchor" href="#硬件接口说明" aria-label="Permalink to &quot;硬件接口说明&quot;">​</a></h2><p>自动限充调用的是本机联想电源管理驱动提供的本地接口，不经过网络，也不依赖 Vantage 运行； 亮度控制走 WMI 或 DDC/CI。你机器上的支持情况可以用 <code>powerkit.exe --selftest</code> 查（只读， 不会改任何设置）。</p>',9)])])}const _=e(i,[["render",n]]);export{p as __pageData,_ as default};
